#include <stdio.h>
#include <stdlib.h>

long binomial_coefficient(int n, int k) {
    if (k == 0 || k == n) {
        return 1;
    }
    if (k > n / 2) {
        k = n - k;
    }
    long result = 1;
    for (int i = 1; i <= k; i++) {
        result = result * (n - i + 1) / i;
    }
    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("Usage: %s <n> <k>\n", argv[0]);
        return 1;
    }
    int n = atoi(argv[1]);
    int k = atoi(argv[2]);
    if (n < 0 || k < 0) {
        printf("Error: n and k must be non-negative.\n");
        return 1;
    }
    if (k > n) {
        printf("Error: k cannot be greater than n.\n");
        return 1;
    }
    long result = binomial_coefficient(n, k);
    printf("%ld\n", result);
    return 0;
}
